int clock_gettime(clockid_t clk_id, struct timespec *tp)
{
	(void)clk_id;
	if (tp == NULL) {
		errno = EINVAL;
		return -1;
	}
	uint32_t ticks = HAL_GetTick();
	tp->tv_sec = ticks / 1000;
	tp->tv_nsec = (ticks % 1000) * 1000000UL;
	return 0;
}

