/**
 _sbrk
 Increase program data space. MALLOC calls this.
 */
caddr_t _sbrk(int incr)
{
	static char *heap_end;
	char *prev_heap_end;
	char *stack_ptr;

	__asm volatile ("MRS %0, msp" : "=r" (stack_ptr));

	if (heap_end == 0)
		heap_end = &_end;

	prev_heap_end = heap_end;
	if (heap_end + incr > stack_ptr)
	{
		errno = ENOMEM;
		return (caddr_t) -1;
	}

	heap_end += incr;
	return (caddr_t) prev_heap_end;
}
